  case "loaded":guard !loaded else{return};loaded=true;evaluate("vncStart("+Self.json(["viewOnly":session.vnc?.viewOnly ?? false])+")")
  case "ready":guard loaded else{return};startConnection()
  case "send":if let encoded=body["data"] as? String {send(encoded)}
  case "connected":guard started else{return};deadline?.invalidate();deadline=nil;transition(.connected,session.vnc?.viewOnly == true ? "已连接 · 只读" : "已连接");focusDesktop()
  case "name":if let value=body["value"] as? String {desktopName.stringValue=String(value.filter{!$0.isNewline && !$0.unicodeScalars.contains(where:{$0.value<32 || $0.value==127})}.prefix(256));desktopName.toolTip=desktopName.stringValue}
