   let stack=NSStackView();stack.orientation = .vertical;stack.alignment = .leading;stack.spacing=8;var fields=[String:NSTextField]()
   for type in types {let label=NSTextField(labelWithString:type=="password" ? "密码" : "用户名");label.font = .systemFont(ofSize:12);stack.addArrangedSubview(label);let field:NSTextField=type=="password" ? NSSecureTextField() : NSTextField(string:session.user);AppTheme.field(field);field.widthAnchor.constraint(equalToConstant:320).isActive=true;field.heightAnchor.constraint(equalToConstant:28).isActive=true;field.setAccessibilityLabel(label.stringValue);stack.addArrangedSubview(field);fields[type]=field};alert.accessoryView=stack;alert.window.initialFirstResponder=types.first.flatMap{fields[$0]};let response=alert.runModal();credentials=response == .alertFirstButtonReturn ? fields.mapValues{$0.stringValue} : nil;for field in fields.values{field.stringValue=""};passwordAlert=nil
